use rhwp::{DocumentCore, model::{control::Control, document::SectionDef, footnote::FootnoteShape, paragraph::Paragraph}, parser::{record::Record,tags}, serializer::{body_text::serialize_paragraph_list,record_writer::write_records}};
use serde_json::{json,Value};
fn repo()->std::path::PathBuf{std::env::var("JUEONY_REPO").unwrap().into()}
fn shape(length:i32,above:i16)->FootnoteShape{FootnoteShape{separator_length:length,separator_margin_top:above,note_spacing:568,raw_unknown:284,separator_line_type:1,separator_line_width:3,separator_color:0x00112233,start_number:7,user_char:'*',prefix_char:'(',suffix_char:')',..Default::default()}}
fn wire(s:&FootnoteShape,legacy:bool)->Vec<u8>{let mut b=s.attr.to_le_bytes().to_vec();for c in [s.user_char,s.prefix_char,s.suffix_char]{b.extend((c as u16).to_le_bytes());}b.extend(s.start_number.to_le_bytes());if legacy{b.extend((s.separator_length as i16).to_le_bytes());}else{b.extend(s.separator_length.to_le_bytes());}b.extend(s.separator_margin_top.to_le_bytes());b.extend(s.note_spacing.to_le_bytes());b.extend(s.raw_unknown.to_le_bytes());b.push(s.separator_line_type);b.push(s.separator_line_width);b.extend(s.separator_color.to_le_bytes());b}
fn records(a:&FootnoteShape,b:&FootnoteShape)->Vec<Record>{let sd=SectionDef{footnote_shape:a.clone(),endnote_shape:b.clone(),..Default::default()};let p=Paragraph{controls:vec![Control::SectionDef(Box::new(sd))],..Default::default()};let mut rr=vec![];serialize_paragraph_list(&[p],0,&mut rr);rr}
fn notes(rr:&[Record])->Vec<Vec<u8>>{rr.iter().filter(|r|r.tag_id==tags::HWPTAG_FOOTNOTE_SHAPE).map(|r|r.data.clone()).collect()}
fn parse_payload(a:&[u8])->FootnoteShape{let mut rr=records(&shape(0,0),&shape(0,0));let r=rr.iter_mut().find(|r|r.tag_id==tags::HWPTAG_FOOTNOTE_SHAPE).unwrap();r.data=a.to_vec();r.size=a.len() as u32;let sec=rhwp::parser::body_text::parse_body_text_section(&write_records(&rr)).unwrap();sec.section_def.footnote_shape}
fn fields(s:&FootnoteShape)->Value{json!({"length":s.separator_length,"above":s.separator_margin_top,"below":s.note_spacing,"between":s.raw_unknown,"type":s.separator_line_type,"width":s.separator_line_width,"color":s.separator_color,"start":s.start_number,"user":s.user_char,"prefix":s.prefix_char,"suffix":s.suffix_char})}
#[test]fn writer_emits_exact_real_28byte_offsets_not_two_i16_length_words(){let a=shape(-1,852);let b=shape(0,864);let n=notes(&records(&a,&b));assert_eq!(n.len(),2);assert_eq!(n[0],wire(&a,false));assert_eq!(n[1],wire(&b,false));assert_eq!(n[0].len(),28);}
#[test]fn independent_native_28byte_fixture_preserves_length_above_below_between(){let a=shape(-1,852);let p=parse_payload(&wire(&a,false));assert_eq!(fields(&p),fields(&a));assert_eq!(p.separator_margin_bottom,0);}
#[test]fn separator_length_preserves_full_signed_i32_range_and_wide_sentinel(){for length in [-1,0,32767,32768,65535,14692344,i32::MIN,i32::MAX]{let a=shape(length,852);let n=notes(&records(&a,&a));assert_eq!(i32::from_le_bytes(n[0][12..16].try_into().unwrap()),length);assert_eq!(fields(&parse_payload(&wire(&a,false))),fields(&a));}}
#[test]fn documented_26byte_legacy_record_has_separate_16bit_layout(){let a=shape(-1,852);let bytes=wire(&a,true);assert_eq!(bytes.len(),26);assert_eq!(fields(&parse_payload(&bytes)),fields(&a));}
#[test]fn signed_spacing_and_color_tail_are_not_shifted_or_clamped(){let mut a=shape(14692344,-123);a.note_spacing=-234;a.raw_unknown=65535;a.separator_color=0x00336699;let bytes=notes(&records(&a,&a)).remove(0);assert_eq!(bytes,wire(&a,false));assert_eq!(fields(&parse_payload(&bytes)),fields(&a));}
#[test]fn actual_xml_note_shapes_export_independently_decodable_native_fields(){let input=std::fs::read(repo().join("build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx")).unwrap();let d=DocumentCore::from_bytes(&input).unwrap();let sd=&d.document().sections[0].section_def;let n=notes(&records(&sd.footnote_shape,&sd.endnote_shape));assert_eq!(n[0],wire(&sd.footnote_shape,false));assert_eq!(n[1],wire(&sd.endnote_shape,false));assert_eq!((sd.footnote_shape.separator_length,sd.footnote_shape.separator_margin_top),(-1,852));assert_eq!((sd.endnote_shape.separator_length,sd.endnote_shape.separator_margin_top),(0,864));}
#[test]fn real_native_mcst_notes_decode_against_independent_record_values(){let input=std::fs::read(repo().join("build/hancom-final-file-review-20261017/source-mcst-bid-2026.hwp")).unwrap();let d=DocumentCore::from_bytes(&input).unwrap();let s=&d.document().sections[0].section_def;assert_eq!((s.footnote_shape.separator_length,s.footnote_shape.separator_margin_top,s.footnote_shape.note_spacing,s.footnote_shape.raw_unknown),(-1,852,568,284));assert_eq!((s.endnote_shape.separator_length,s.endnote_shape.separator_margin_top,s.endnote_shape.note_spacing,s.endnote_shape.raw_unknown),(0,864,576,0));}
#[test]fn real_endnote_api_history_and_native_storage_keep_all_requested_spacing(){let mut d=DocumentCore::new_empty();d.create_blank_document_native().unwrap();let before=d.save_snapshot_native();d.apply_endnote_shape_native(0,r##"{"separatorLength":12345,"separatorMarginTop":852,"separatorMarginBottom":568,"noteSpacing":284,"separatorLineType":1,"separatorLineWidth":2,"separatorColor":"#112233"}"##).unwrap();let requested:Value=serde_json::from_str(&d.get_endnote_shape_native(0).unwrap()).unwrap();let redo=d.save_snapshot_native();d.restore_snapshot_native(before).unwrap();d.restore_snapshot_native(redo).unwrap();let artifact=d.export_hwp_with_adapter_snapshot_with_report().unwrap();let r=DocumentCore::from_bytes(artifact.bytes()).unwrap();let actual:Value=serde_json::from_str(&r.get_endnote_shape_native(0).unwrap()).unwrap();assert_eq!(requested,actual);let s=&r.document().sections[0].section_def.endnote_shape;assert_eq!((s.separator_length,s.separator_margin_top,s.note_spacing,s.raw_unknown),(12345,852,568,284));}
#[test]fn hwp3_native_conversion_retains_independent_separator_and_spacing(){let input=std::fs::read(repo().join("upstream/rhwp-source/samples/hwp3-pagedef-1915.hwp")).unwrap();let d=rhwp::parser::parse_document(&input).unwrap();let saved=rhwp::serializer::serialize_document(&d).unwrap();let r=rhwp::parser::parse_document(&saved).unwrap();for(a,b)in d.sections.iter().zip(&r.sections){for(x,y)in[(&a.section_def.footnote_shape,&b.section_def.footnote_shape),(&a.section_def.endnote_shape,&b.section_def.endnote_shape)]{assert_eq!(x.separator_length,y.separator_length);assert_eq!(x.separator_above_margin_hu(),y.separator_above_margin_hu());assert_eq!(x.separator_below_margin_hu(),y.separator_below_margin_hu());assert_eq!(x.between_notes_margin_hu(),y.between_notes_margin_hu());}}}
#[test]fn compiled_codec_sources_are_exactly_the_selected_physical_source(){for(name,compiled)in[("src/parser/body_text.rs",include_str!("../src/parser/body_text.rs")),("src/serializer/control.rs",include_str!("../src/serializer/control.rs")),("src/parser/hwp3/mod.rs",include_str!("../src/parser/hwp3/mod.rs")),("src/document_core/commands/object_ops/shape.rs",include_str!("../src/document_core/commands/object_ops/shape.rs"))]{let raw=std::fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(name)).unwrap();assert_eq!(compiled.as_bytes(),raw);use sha2::{Digest,Sha256};let h=Sha256::digest(raw).iter().map(|v|format!("{v:02x}")).collect::<String>();println!("COMPILED_SOURCE {name} {h}");}}
fn published(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|p|json!({"control":serde_json::from_str::<Value>(&d.get_page_control_layout_native(p).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(p).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn exact_geometry(a:&Value,b:&Value,path:&str){match(a,b){(Value::Number(x),Value::Number(y))=>{let x=x.as_f64().unwrap();let y=y.as_f64().unwrap();assert!(x.is_finite()&&y.is_finite()&&(x-y).abs()<=0.2,"numeric geometry at {path}");},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"array geometry length at {path}");for(i,(x,y))in x.iter().zip(y).enumerate(){exact_geometry(x,y,&format!("{path}/{i}"));}},(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"object key count at {path}");for(k,x)in x{let y=y.get(k).unwrap_or_else(||panic!("missing layout key {path}/{k}"));exact_geometry(x,y,&format!("{path}/{k}"));}},_=>assert!(a==b,"exact layout field at {path}")}}
#[test]fn actual_document_both_formats_twice_keep_native_note_bytes_and_published_layout(){
 let input=std::fs::read(repo().join("build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx")).unwrap();let d=DocumentCore::from_bytes(&input).unwrap();assert_eq!(d.page_count(),16);let before=published(&d);let sd=&d.document().sections[0].section_def;let fn_fields=fields(&sd.footnote_shape);let en_fields=fields(&sd.endnote_shape);let mut proof=vec![];
 for format in["hwp","hwpx"]{let mut current=DocumentCore::from_bytes(&input).unwrap();for cycle in 1..=2{
  let artifact=if format=="hwp"{current.export_hwp_with_adapter_snapshot_with_report().unwrap()}else{current.export_hwpx_native_with_report().unwrap()};assert!(artifact.content_loss().is_empty(),"no hidden content loss");let reopened=DocumentCore::from_bytes(artifact.bytes()).unwrap();assert_eq!(reopened.page_count(),16);exact_geometry(&before,&published(&reopened),"pages");let sd=&reopened.document().sections[0].section_def;assert_eq!(fields(&sd.footnote_shape),fn_fields);assert_eq!(fields(&sd.endnote_shape),en_fields);
  if format=="hwp"&&cycle==1{std::fs::write(repo().join("build/note-shape-i32-candidate82/mcst-note-i32-native-review.hwp"),artifact.bytes()).unwrap();}
  use sha2::{Digest,Sha256};proof.push(json!({"format":format,"cycle":cycle,"pages":16,"geometryDifferences":0,"footnote":fields(&sd.footnote_shape),"endnote":fields(&sd.endnote_shape),"outputSha256":Sha256::digest(artifact.bytes()).iter().map(|v|format!("{v:02x}")).collect::<String>()}));current=reopened;
 }}exact_geometry(&before,&published(&d),"liveSource");assert_eq!(std::fs::read(repo().join("build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx")).unwrap(),input);std::fs::write(repo().join("build/note-shape-i32-candidate82/actual-native-roundtrip-proof.json"),serde_json::to_vec_pretty(&json!({"results":proof,"sourceUnchanged":true,"bodyOrSnapshotsWritten":false,"reviewFileIgnoredPublicDerivative":true})).unwrap()).unwrap();
}
